using ProMaxx2.QA.Application.Common;using ProMaxx2.QA.Application.Projects;using ProMaxx2.QA.Domain.TestManagement;
namespace ProMaxx2.QA.Application.TestManagement;
public sealed record SuiteCaseDto(Guid TestCaseId,string TestCaseCode,string Title,string Priority,int SortOrder,bool IsRequired);public sealed record TestSuiteDto(Guid TestSuiteId,Guid ProjectId,string SuiteCode,string SuiteName,string?SuiteType,string?Description,string?RiskTier,bool IsActive,IReadOnlyList<SuiteCaseDto>Cases);public sealed record SaveTestSuiteRequest(Guid ProjectId,string SuiteCode,string SuiteName,string?SuiteType,string?Description,string?RiskTier,bool IsActive=true);public sealed record AddSuiteCasesRequest(IReadOnlyList<Guid>TestCaseIds,bool IsRequired);public interface ITestSuiteRepository{Task<IReadOnlyList<TestSuiteDto>>ListAsync(Guid?projectId,string?search,CancellationToken ct);Task<TestSuiteDto?>GetAsync(Guid id,CancellationToken ct);Task<TestSuite?>FindAsync(Guid id,CancellationToken ct);Task<bool>CodeExistsAsync(Guid projectId,string code,Guid?excludeId,CancellationToken ct);Task AddAsync(TestSuite suite,CancellationToken ct);Task AddCasesAsync(Guid id,IReadOnlyList<Guid>caseIds,bool required,CancellationToken ct);Task RemoveCaseAsync(Guid id,Guid caseId,CancellationToken ct);Task SaveAsync(CancellationToken ct);}
public sealed class TestSuiteService(ITestSuiteRepository repository,IProjectRepository projects){public Task<IReadOnlyList<TestSuiteDto>>ListAsync(Guid?p,string?s,CancellationToken ct)=>repository.ListAsync(p,s,ct);public async Task<TestSuiteDto>GetAsync(Guid id,CancellationToken ct)=>await repository.GetAsync(id,ct)??throw new EntityNotFoundException("Test suite not found.");public async Task<TestSuiteDto>CreateAsync(SaveTestSuiteRequest r,CancellationToken ct){var project=await projects.GetAsync(r.ProjectId,ct)??throw new EntityNotFoundException("Project not found.");var code=string.IsNullOrWhiteSpace(r.SuiteCode)?await BusinessCodeGenerator.NextAvailableAsync($"{project.ProjectCode}-TS",candidate=>repository.CodeExistsAsync(r.ProjectId,candidate,null,ct)):r.SuiteCode.Trim().ToUpperInvariant();if(await repository.CodeExistsAsync(r.ProjectId,code,null,ct))throw new DuplicateCodeException("Suite code already exists.");var entity=new TestSuite(r.ProjectId,code,r.SuiteName,r.SuiteType,r.Description,r.RiskTier);await repository.AddAsync(entity,ct);await repository.SaveAsync(ct);return(await repository.GetAsync(entity.TestSuiteId,ct))!;}public async Task<TestSuiteDto>UpdateAsync(Guid id,SaveTestSuiteRequest r,CancellationToken ct){var entity=await repository.FindAsync(id,ct)??throw new EntityNotFoundException("Test suite not found.");entity.Update(r.SuiteName,r.SuiteType,r.Description,r.RiskTier,r.IsActive);await repository.SaveAsync(ct);return(await repository.GetAsync(id,ct))!;}public async Task DeactivateAsync(Guid id,CancellationToken ct){var entity=await repository.FindAsync(id,ct)??throw new EntityNotFoundException("Test suite not found.");entity.Deactivate();await repository.SaveAsync(ct);}public async Task AddCasesAsync(Guid id,AddSuiteCasesRequest r,CancellationToken ct){_=await repository.FindAsync(id,ct)??throw new EntityNotFoundException("Test suite not found.");await repository.AddCasesAsync(id,r.TestCaseIds,r.IsRequired,ct);await repository.SaveAsync(ct);}public async Task RemoveCaseAsync(Guid id,Guid caseId,CancellationToken ct){await repository.RemoveCaseAsync(id,caseId,ct);await repository.SaveAsync(ct);}}
